import type { LearningLesson } from "./learning-resources";

type Topic = { id: string; title: string; section: string; summary: string; content: string[]; example: string; output?: string; level?: LearningLesson["level"] };

function makeLesson(topic: Topic): LearningLesson {
  return {
    ...topic,
    contentLanguage: "en",
    examples: [{ title: "Try it", code: topic.example, result: topic.output }],
    quiz: {
      question: `What is the main idea of ${topic.title}?`,
      options: [topic.summary, "It is a special kind of comment", "It automatically fixes every program error"],
      answer: 0,
      explanation: topic.summary,
    },
  };
}

const topics: Topic[] = [
  { id:"intro", title:"C introduction", section:"C Tutorial", summary:"C is a compiled, general-purpose language used for systems, embedded devices, and performance-focused programs.", content:["C gives you close control over data and memory while still providing functions, types, and standard libraries. A compiler translates source code into a program your computer can run.","C is standardized by ISO; compilers may offer extensions. This course uses portable, modern C patterns. Save examples as .c files, compile with a C compiler, then run the resulting program."], example:"#include <stdio.h>\n\nint main(void) {\n    puts(\"Hello, C!\");\n    return 0;\n}", output:"Hello, C!" },
  { id:"get-started",title:"Get started with C",section:"C Tutorial",summary:"Write a .c source file, compile it with a C compiler, and run the executable.",content:["Install a compiler such as GCC, Clang, or a platform's C toolchain. A common command is `cc -std=c17 -Wall -Wextra -Wpedantic hello.c -o hello`; compiler commands vary by operating system.","Warnings help catch mistakes early. Keep the source file and compiler output separate, and read the first diagnostic carefully when compilation fails."],example:"/* Save as hello.c, then compile: cc -std=c17 -Wall -Wextra hello.c -o hello */\n#include <stdio.h>\nint main(void) { puts(\"Ready to learn C\"); return 0; }",output:"Ready to learn C"},
  { id:"syntax",title:"C syntax",section:"C Tutorial",summary:"C statements usually end in semicolons, blocks use braces, and names are case-sensitive.",content:["A program is made from declarations, functions, and statements. Braces `{}` group a block, and `;` ends most declarations and statements. `main` is the usual program entry point.","C distinguishes uppercase and lowercase names: `total` and `Total` are different. Indentation is not required by the compiler, but consistent formatting makes blocks easier to follow."],example:"#include <stdio.h>\n\nint main(void) {\n    int total = 2 + 3;\n    printf(\"Total: %d\\n\", total);\n    return 0;\n}",output:"Total: 5"},
  { id:"output",title:"Output",section:"C Tutorial",summary:"Use printf for formatted output and puts for a line of plain text.",content:["Include `<stdio.h>` to use standard input and output functions. `printf` uses a format string: `%d` for int, `%f` for double, and `%s` for a null-terminated string.","Each format marker must match the type of its corresponding argument; a mismatch can cause undefined behavior. `\\n` starts a new line. Check `printf`'s return value when output errors matter."],example:"#include <stdio.h>\nint main(void) {\n    int count = 3;\n    printf(\"Items: %d\\n\", count);\n    return 0;\n}",output:"Items: 3"},
  { id:"comments",title:"Comments",section:"C Tutorial",summary:"Comments explain intent to people and are ignored by the compiler.",content:["Use `//` for a short comment through the end of a line and `/* ... */` for a block comment. Block comments cannot be nested in C.","Prefer comments that explain why a decision exists. Clear names and simple code are usually better than comments that just repeat each statement."],example:"#include <stdio.h>\nint main(void) {\n    // Keep the discount in one named value.\n    const int discount_percent = 10;\n    printf(\"Discount: %d%%\\n\", discount_percent);\n    return 0;\n}",output:"Discount: 10%"},
  { id:"variables",title:"Variables",section:"C Tutorial",summary:"A variable is a named object with a type and a value that can be updated.",content:["Declare a variable with its type before using it, such as `int score = 0;`. Initialization gives it a known starting value; reading an uninitialized automatic variable is a bug.","Choose descriptive names and keep a variable's purpose narrow. Use `const` when code should not modify an object through that name."],example:"#include <stdio.h>\nint main(void) {\n    int score = 10;\n    score += 5;\n    printf(\"Score: %d\\n\", score);\n    return 0;\n}",output:"Score: 15"},
  { id:"data-types",title:"Data types",section:"C Tutorial",summary:"C types describe what values an object can hold and how operations interpret them.",content:["Common types include `char`, `int`, `float`, and `double`; `_Bool` represents truth values, and `<stdbool.h>` provides `bool`, `true`, and `false` in C99 and later. Exact sizes can depend on the implementation.","Use `sizeof` to inspect object sizes on the current system. Use `<stdint.h>` fixed-width types such as `int32_t` when an exact width is required and the implementation provides it."],example:"#include <stdio.h>\n#include <stdbool.h>\nint main(void) {\n    int age = 16;\n    bool learning = true;\n    printf(\"age=%d, learning=%d\\n\", age, learning);\n    return 0;\n}",output:"age=16, learning=1"},
  { id:"type-conversion",title:"Type conversion",section:"C Tutorial",summary:"Conversions change how values are represented, so check for truncation and range loss.",content:["C applies some conversions automatically, such as promoting small integer types in expressions. Converting a floating value to an integer discards the fractional part toward zero.","A cast like `(double) total` makes a conversion explicit, but it does not make an out-of-range conversion safe. Check ranges before converting and choose suitable types for the calculation."],example:"#include <stdio.h>\nint main(void) {\n    int total = 7, people = 2;\n    double average = (double) total / people;\n    printf(\"Average: %.1f\\n\", average);\n    return 0;\n}",output:"Average: 3.5"},
  { id:"constants",title:"Constants",section:"C Tutorial",summary:"Use const to prevent modification through a name and macros for compile-time text substitution.",content:["A `const` object must be initialized when required by its storage duration and cannot be modified through that identifier. Prefer it for values that should remain fixed during a function.","`#define` creates a preprocessor macro, not a typed variable. Use parentheses in expression macros and avoid macros with side effects; a `const` object or function is often safer."],example:"#include <stdio.h>\nint main(void) {\n    const double pi = 3.14159;\n    double radius = 2.0;\n    printf(\"Area: %.2f\\n\", pi * radius * radius);\n    return 0;\n}",output:"Area: 12.57"},
  { id:"operators",title:"Operators",section:"C Tutorial",summary:"Operators combine or compare values to produce results.",content:["Arithmetic operators include `+`, `-`, `*`, `/`, and `%` for integer remainder. Comparisons produce a truth value; logical operators `&&`, `||`, and `!` combine conditions.","Integer division truncates toward zero. Operator precedence can be hard to scan, so add parentheses when they make the intended order clearer. Avoid modifying the same object multiple times in an expression."],example:"#include <stdio.h>\nint main(void) {\n    int apples = 10;\n    int people = 3;\n    printf(\"Each: %d, left: %d\\n\", apples / people, apples % people);\n    return 0;\n}",output:"Each: 3, left: 1"},
  { id:"booleans",title:"Booleans",section:"C Tutorial",summary:"Conditions in C treat zero as false and nonzero as true; stdbool.h offers bool names.",content:["In C, comparisons such as `score >= 50` produce 0 or 1. Include `<stdbool.h>` to use the readable names `bool`, `true`, and `false`.","Do not compare a boolean-like value to `true` when the condition itself is clearer. Use `==` for equality; a single `=` assigns a value."],example:"#include <stdio.h>\n#include <stdbool.h>\nint main(void) {\n    int score = 82;\n    bool passed = score >= 50;\n    printf(\"Passed: %s\\n\", passed ? \"yes\" : \"no\");\n    return 0;\n}",output:"Passed: yes"},
  { id:"if-else",title:"If and else",section:"C Tutorial",summary:"if and else choose which block runs based on a condition.",content:["An `if` statement runs its block when its expression is nonzero. Add `else if` for more cases and `else` for a fallback. Braces are recommended even for one-line blocks.","Order branches from specific cases to general cases. Conditions should be readable and should not rely on side effects."],example:"#include <stdio.h>\nint main(void) {\n    int temperature = 18;\n    if (temperature < 10) puts(\"Cold\");\n    else if (temperature < 25) puts(\"Mild\");\n    else puts(\"Warm\");\n    return 0;\n}",output:"Mild"},
  { id:"switch",title:"Switch",section:"C Tutorial",summary:"switch selects a matching integer or enumeration case and break prevents fall-through.",content:["`switch` is useful when one integer-like expression is compared with several constant case labels. Execution continues into following cases until it reaches `break`, `return`, or the end of the switch.","Use `default` for unlisted values. Intentional fall-through should be clearly marked; otherwise include a break to avoid accidental behavior."],example:"#include <stdio.h>\nint main(void) {\n    int day = 2;\n    switch (day) {\n        case 1: puts(\"Monday\"); break;\n        case 2: puts(\"Tuesday\"); break;\n        default: puts(\"Another day\");\n    }\n    return 0;\n}",output:"Tuesday"},
  { id:"while",title:"While loop",section:"C Tutorial",summary:"A while loop repeats its body as long as its condition is true.",content:["The `while` condition is checked before every iteration, so the body may run zero times. Update the state used by the condition to ensure the loop eventually stops.","Use `do ... while` when the body must run at least once. Avoid empty loops and make loop exit conditions easy to understand."],example:"#include <stdio.h>\nint main(void) {\n    int count = 1;\n    while (count <= 3) {\n        printf(\"%d \", count);\n        count++;\n    }\n    puts(\"done\");\n    return 0;\n}",output:"1 2 3 done"},
  { id:"for",title:"For loop",section:"C Tutorial",summary:"A for loop places initialization, continuation condition, and update in one header.",content:["A `for` loop has the form `for (initialization; condition; update)`. The condition is checked before each iteration; `continue` proceeds to the update step.","Use it for counted repetition or array traversal. Keep the index within bounds: a valid index for an array of length n is from 0 through n-1."],example:"#include <stdio.h>\nint main(void) {\n    for (int i = 0; i < 4; i++) {\n        printf(\"%d \", i);\n    }\n    puts(\"done\");\n    return 0;\n}",output:"0 1 2 3 done"},
  { id:"break-continue",title:"Break and continue",section:"C Tutorial",summary:"break exits the nearest loop or switch, while continue starts the next loop iteration.",content:["`break` leaves the nearest enclosing loop or switch. `continue` skips the rest of the current loop body and starts the next iteration.","Use these statements when they make an early exit or skipped case easier to read. Deeply nested control flow may be clearer when split into a function."],example:"#include <stdio.h>\nint main(void) {\n    for (int n = 1; n <= 5; n++) {\n        if (n == 2) continue;\n        if (n == 4) break;\n        printf(\"%d \", n);\n    }\n    return 0;\n}",output:"1 3 "},
  { id:"arrays",title:"Arrays",section:"C Tutorial",summary:"An array stores a fixed number of same-type elements next to one another.",content:["Array indices start at zero. An array declared with five elements has valid indices 0 through 4; accessing outside that range has undefined behavior.","An array does not carry its length when passed to a function, so pass the length separately. Initialize arrays explicitly when they need known values."],example:"#include <stdio.h>\nint main(void) {\n    int scores[] = {82, 95, 73};\n    size_t count = sizeof scores / sizeof scores[0];\n    for (size_t i = 0; i < count; i++) printf(\"%d \", scores[i]);\n    return 0;\n}",output:"82 95 73"},
  { id:"strings",title:"Strings",section:"C Tutorial",summary:"A C string is a char array ending with the null character '\\0'.",content:["C has no built-in string object. A string is a sequence of `char` values with a terminating null character. Reserve space for that terminator as well as the visible characters.","Use bounded input and operations, track buffer capacity, and avoid copying more data than a destination can hold. String functions are declared in `<string.h>`. Never use `gets`, which was removed from the C standard."],example:"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char name[16] = \"Mira\";\n    printf(\"%s has %zu letters\\n\", name, strlen(name));\n    return 0;\n}",output:"Mira has 4 letters"},
  { id:"user-input",title:"User input",section:"C Tutorial",summary:"Read input with functions such as fgets and check whether reading and conversion succeeded.",content:["`fgets` reads at most the buffer capacity minus one characters and adds a null terminator. Check its return value to detect end-of-file or an error.","For numeric input, read a line and parse it with `strtol` or related functions; check that conversion succeeded and that the result is in range. `scanf` needs careful format and return-value checks."],example:"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char name[40];\n    fputs(\"Name: \", stdout);\n    if (fgets(name, sizeof name, stdin)) {\n        name[strcspn(name, \"\\n\")] = '\\0';\n        printf(\"Hello, %s!\\n\", name);\n    }\n    return 0;\n}",output:"For input Ada: Hello, Ada!"},
  { id:"memory-address",title:"Memory addresses",section:"C Tutorial",summary:"The address-of operator & obtains an object's address for use with a compatible pointer.",content:["Each object stored in memory has an address during its lifetime. The unary `&` operator produces a pointer to an object; `%p` prints a pointer when converted to `void *`.","Addresses are not ordinary integers and should not be guessed or hard-coded. An object's address is valid only while that object exists."],example:"#include <stdio.h>\nint main(void) {\n    int value = 42;\n    printf(\"value=%d, address=%p\\n\", value, (void *)&value);\n    return 0;\n}",output:"Shows value=42 and a system-dependent address"},
  { id:"pointers",title:"Pointers",section:"C Tutorial",summary:"A pointer stores an address; dereferencing a valid pointer accesses the pointed-to object.",content:["Declare a pointer with a type such as `int *pointer`. Initialize it to a valid object's address or to `NULL` before use. The `*` operator dereferences it, so the pointer must be valid and correctly aligned.","Pointers do not own objects automatically. Never dereference a null, uninitialized, expired, or out-of-bounds pointer. Match pointer types and respect each object's lifetime."],example:"#include <stdio.h>\nint main(void) {\n    int value = 7;\n    int *pointer = &value;\n    *pointer = 9;\n    printf(\"%d\\n\", value);\n    return 0;\n}",output:"9"},
  { id:"functions",title:"Functions",section:"C Functions",summary:"Functions package reusable work behind a name, parameters, and a return type.",content:["A function definition specifies its return type, name, parameters, and body. `void` means no return value or, in a parameter list, no parameters. Return values let a function report a result to its caller.","Keep functions focused and validate their inputs where appropriate. C passes arguments by value; pointer parameters let a function access or modify another object when that is intended."],example:"#include <stdio.h>\nint add(int left, int right) { return left + right; }\nint main(void) {\n    printf(\"%d\\n\", add(2, 3));\n    return 0;\n}",output:"5"},
  { id:"function-parameters",title:"Function parameters",section:"C Functions",summary:"Parameters receive copies of argument values when a function is called.",content:["A function's parameter list describes the values it accepts. C passes each argument by value, so assigning a new value to a parameter does not change the caller's variable.","For large read-only data, a pointer to `const` can avoid copying and signal that the function will not change the object. Pass array lengths explicitly alongside array pointers."],example:"#include <stdio.h>\nint square(int number) { return number * number; }\nint main(void) {\n    int value = 4;\n    printf(\"%d squared is %d\\n\", value, square(value));\n    return 0;\n}",output:"4 squared is 16"},
  { id:"pass-by-reference",title:"Passing pointers to functions",section:"C Functions",summary:"Pass an object's address when a function needs to update that object.",content:["C does not have pass-by-reference parameters. Instead, pass a pointer value; the function can dereference it to access the caller's object.","Document whether a pointer may be null and whether the function changes the pointed-to data. Check pointers before dereferencing when null is an allowed input."],example:"#include <stdio.h>\nvoid add_one(int *value) { if (value) (*value)++; }\nint main(void) {\n    int count = 4;\n    add_one(&count);\n    printf(\"%d\\n\", count);\n    return 0;\n}",output:"5"},
  { id:"scope",title:"Scope",section:"C Functions",summary:"Scope determines where a name can be used in the source code.",content:["A block-scope name is visible from its declaration to the end of its block. A file-scope declaration is visible from its point of declaration through the source file, subject to linkage rules.","Prefer local variables over global state when possible. Smaller scopes reduce accidental reuse and make code easier to understand."],example:"#include <stdio.h>\nint main(void) {\n    int outer = 1;\n    { int inner = 2; printf(\"%d %d\\n\", outer, inner); }\n    return 0;\n}",output:"1 2"},
  { id:"function-declaration",title:"Function declarations",section:"C Functions",summary:"A function declaration tells the compiler a function's name, return type, and parameter types.",content:["A prototype such as `int add(int, int);` lets the compiler check calls before it sees the function definition. Put declarations shared by files in a header, with appropriate include guards.","In modern C, write `(void)` to declare a function that takes no parameters. A declaration with empty parentheses does not provide the same parameter information."],example:"#include <stdio.h>\nint add(int left, int right);\nint main(void) { printf(\"%d\\n\", add(3, 4)); return 0; }\nint add(int left, int right) { return left + right; }",output:"7"},
  { id:"math-functions",title:"Math functions",section:"C Functions",summary:"The math library provides functions such as sqrt, pow, and fabs.",content:["Include `<math.h>` to declare standard math functions. For example, `sqrt` calculates a square root and `pow` raises one value to another.","Some toolchains require linking the math library separately, commonly with `-lm`. Check domains, ranges, and floating-point rounding in calculations."],example:"#include <math.h>\n#include <stdio.h>\nint main(void) {\n    printf(\"sqrt(81) = %.1f\\n\", sqrt(81.0));\n    return 0;\n}",output:"sqrt(81) = 9.0"},
  { id:"inline-functions",title:"Inline functions",section:"C Functions",summary:"inline is a suggestion about function linkage and inlining, not a guarantee of faster code.",content:["An `inline` function is still an ordinary function with type checking and function-call semantics. The compiler decides whether to inline it; the keyword does not promise a speed improvement.","Inline definitions in headers need careful linkage rules. For small helpers, macros are often unnecessary and can be less safe than functions."],example:"#include <stdio.h>\nstatic inline int triple(int value) { return value * 3; }\nint main(void) { printf(\"%d\\n\", triple(4)); return 0; }",output:"12"},
  { id:"recursion",title:"Recursion",section:"C Functions",summary:"A recursive function calls itself and needs a base case that stops the calls.",content:["A recursive solution reduces a problem into smaller instances. Every path must reach a base case; otherwise calls continue until resources are exhausted.","Recursion can make tree-like problems clear, but deep input may overflow the call stack. Consider an iterative approach when input depth can be large."],example:"#include <stdio.h>\nunsigned long factorial(unsigned int n) {\n    if (n < 2) return 1;\n    return n * factorial(n - 1);\n}\nint main(void) { printf(\"%lu\\n\", factorial(5)); return 0; }",output:"120"},
  { id:"function-pointers",title:"Function pointers",section:"C Functions",summary:"A function pointer stores a function's address so behavior can be passed or selected.",content:["A function pointer's type includes the function's return type and parameter types. Use a `typedef` to make complicated callback types easier to read.","Call only a pointer to a compatible function. Check for null when an optional callback is allowed to be absent."],example:"#include <stdio.h>\nint double_value(int n) { return n * 2; }\nint main(void) {\n    int (*operation)(int) = double_value;\n    printf(\"%d\\n\", operation(6));\n    return 0;\n}",output:"12"},
  { id:"files-create",title:"Create and open files",section:"C Files",summary:"fopen opens a file stream and returns NULL when it cannot open the requested file.",content:["Include `<stdio.h>` and call `fopen` with a path and mode such as `\"w\"` for writing or `\"r\"` for reading. Check the returned pointer before using the stream.","The `\"w\"` mode truncates an existing file. Choose modes carefully, handle errors, and close a successfully opened stream with `fclose`."],example:"#include <stdio.h>\nint main(void) {\n    FILE *file = fopen(\"notes.txt\", \"w\");\n    if (!file) { perror(\"notes.txt\"); return 1; }\n    fputs(\"First note\\n\", file);\n    if (fclose(file) == EOF) { perror(\"close\"); return 1; }\n    return 0;\n}"},
  { id:"files-write",title:"Write to files",section:"C Files",summary:"Use stdio functions such as fprintf and fputs to write text to an open file stream.",content:["`fprintf` formats text into a stream, while `fputs` writes a string. Check return values when failed writes need to be detected; buffered errors may also appear when closing the stream.","Open files using a suitable mode and close them once finished. Never assume a path is writable or that every write succeeds."],example:"#include <stdio.h>\nint main(void) {\n    FILE *file = fopen(\"scores.txt\", \"w\");\n    if (!file) return 1;\n    int result = fprintf(file, \"Score: %d\\n\", 95);\n    int close_result = fclose(file);\n    return result < 0 || close_result == EOF;\n}"},
  { id:"files-read",title:"Read files",section:"C Files",summary:"Read file streams with functions such as fgets and detect end-of-file or errors.",content:["`fgets` reads a bounded line from a stream and returns null when it cannot read another line. A line may not fit in one buffer, so handle long lines deliberately.","Check `ferror` to distinguish a read error from normal end-of-file when that matters. Close files on every path after opening."],example:"#include <stdio.h>\nint main(void) {\n    FILE *file = fopen(\"notes.txt\", \"r\");\n    if (!file) { perror(\"notes.txt\"); return 1; }\n    char line[128];\n    while (fgets(line, sizeof line, file)) fputs(line, stdout);\n    int failed = ferror(file);\n    fclose(file);\n    return failed;\n}"},
  { id:"structs",title:"Structures",section:"C Structures",summary:"A struct groups named members, which may have different types, into one object.",content:["Define a `struct` type to model a record with related fields. Use the dot operator to access a member of a struct object.","Initialize fields clearly, often with a designated initializer. A structure assignment copies its members, but any pointer members still point to the same referenced objects."],example:"#include <stdio.h>\nstruct Point { int x; int y; };\nint main(void) {\n    struct Point origin = {.x = 0, .y = 0};\n    printf(\"(%d, %d)\\n\", origin.x, origin.y);\n    return 0;\n}",output:"(0, 0)"},
  { id:"nested-structs",title:"Nested structures",section:"C Structures",summary:"A structure can contain another structure as a member to represent related data.",content:["A struct member can itself be a struct, letting a record contain smaller records. Access nested fields by chaining the dot operator.","Nested structs keep related information together. Choose a clear design and avoid copying large records unnecessarily."],example:"#include <stdio.h>\nstruct Date { int day, month, year; };\nstruct Event { const char *name; struct Date date; };\nint main(void) {\n    struct Event event = {\"Study group\", {12, 5, 2026}};\n    printf(\"%s: %02d/%02d/%d\\n\", event.name, event.date.day, event.date.month, event.date.year);\n    return 0;\n}",output:"Study group: 12/05/2026"},
  { id:"arrays-of-structs",title:"Arrays of structures",section:"C Structures",summary:"An array of structures stores multiple records of the same struct type.",content:["Each element in a struct array is a complete record. Use an index to access an element, then `.` to access one of its members.","Keep the element count with the array or pass it to helper functions. Avoid indexing beyond the number of initialized or allocated elements."],example:"#include <stdio.h>\nstruct Score { const char *name; int points; };\nint main(void) {\n    struct Score scores[] = {{\"Ari\", 8}, {\"Lee\", 10}};\n    for (size_t i = 0; i < 2; i++) printf(\"%s: %d\\n\", scores[i].name, scores[i].points);\n    return 0;\n}",output:"Ari: 8\nLee: 10"},
  { id:"structs-pointers",title:"Structures and pointers",section:"C Structures",summary:"Use -> to access a struct member through a pointer to that structure.",content:["For a struct object, use `.`; for a pointer to a struct, use `->`. The expression `pointer->member` is shorthand for `(*pointer).member`.","The pointer must refer to a live struct before you use `->`. A pointer to const struct allows reading members without modifying them through that pointer."],example:"#include <stdio.h>\nstruct Point { int x, y; };\nint main(void) {\n    struct Point point = {2, 5};\n    struct Point *pointer = &point;\n    pointer->x = 8;\n    printf(\"%d, %d\\n\", point.x, point.y);\n    return 0;\n}",output:"8, 5"},
  { id:"unions",title:"Unions",section:"C Structures",summary:"A union lets its members share storage, so typically only the most recently written member is active.",content:["A union has members that occupy overlapping storage. Its size is enough for its largest member, with alignment as required by the implementation.","Track which member the program currently uses, often with an accompanying enum tag. Reading a different member than the one most recently written requires care and is not a general-purpose conversion."],example:"#include <stdio.h>\nunion Number { int whole; float decimal; };\nint main(void) {\n    union Number value = {.whole = 12};\n    printf(\"%d\\n\", value.whole);\n    return 0;\n}",output:"12"},
  { id:"typedef",title:"typedef",section:"C Structures",summary:"typedef gives an existing type another name to make declarations easier to read.",content:["A `typedef` creates an alias; it does not create a completely new distinct type. It is commonly used to shorten struct names or describe function-pointer types.","Use aliases when they improve clarity, especially for meaningful domain concepts. Hiding pointer types behind aliases can make ownership and mutability less obvious."],example:"#include <stdio.h>\ntypedef struct { int x, y; } Point;\nint main(void) {\n    Point marker = {.x = 3, .y = 6};\n    printf(\"%d, %d\\n\", marker.x, marker.y);\n    return 0;\n}",output:"3, 6"},
  { id:"struct-padding",title:"Structure padding",section:"C Structures",summary:"The compiler may insert padding bytes to meet member alignment requirements.",content:["A structure's members appear in declaration order, but padding may be added between members or at the end. This means `sizeof(struct)` can exceed the sum of member sizes.","Do not assume a fixed layout for files or network messages by writing raw struct bytes. Padding, byte order, and representations can differ; serialize fields explicitly."],example:"#include <stdio.h>\nstruct Sample { char tag; int count; };\nint main(void) {\n    printf(\"struct size: %zu bytes\\n\", sizeof(struct Sample));\n    return 0;\n}",output:"The size depends on the compiler and platform"},
  { id:"enums",title:"Enumerations",section:"C Enums",summary:"An enum defines named integer constants that make a set of choices easier to read.",content:["Declare an enum for a finite set of named states. The values are integer constants; unless assigned explicitly, they start at zero and increase by one.","Enums improve readability but C does not enforce that a variable contains only one of the named values. Validate values that come from input or external data."],example:"#include <stdio.h>\nenum TrafficLight { RED, YELLOW, GREEN };\nint main(void) {\n    enum TrafficLight light = GREEN;\n    printf(\"green=%d\\n\", light == GREEN);\n    return 0;\n}",output:"green=1"},
  { id:"memory-management",title:"Memory management overview",section:"C Memory",summary:"Dynamic memory must have a clear owner, a valid size, and a matching release.",content:["Automatic objects usually live until their block ends; allocated objects live until released. Dynamic allocation is useful when size or lifetime is not known at compile time.","Every successful allocation should have a clear owner and a path to `free`. Avoid use-after-free, double-free, leaks, and arithmetic overflow when computing allocation sizes."],example:"#include <stdlib.h>\nint main(void) {\n    int *value = malloc(sizeof *value);\n    if (!value) return 1;\n    *value = 42;\n    free(value);\n    value = NULL;\n    return 0;\n}"},
  { id:"allocate-memory",title:"Allocate memory",section:"C Memory",summary:"malloc and calloc request dynamic memory and return NULL if allocation fails.",content:["`malloc(bytes)` allocates uninitialized storage; `calloc(count, size)` allocates zeroed storage. Both return `void *`, which C can convert to an object pointer without a cast.","Check for null before using the result. Calculate sizes safely and allocate using `sizeof *pointer` so the type stays in sync with the declaration."],example:"#include <stdlib.h>\nint main(void) {\n    size_t count = 4;\n    int *values = calloc(count, sizeof *values);\n    if (!values) return 1;\n    values[0] = 10;\n    free(values);\n    return 0;\n}"},
  { id:"access-memory",title:"Access dynamically allocated memory",section:"C Memory",summary:"Use allocated memory only within its size and only while its allocation is still alive.",content:["Allocation provides a region of bytes, but the program must track how many elements fit. Valid array indices are less than the allocated element count.","Accessing freed memory or stepping outside the region has undefined behavior. Keep pointer and length together in your design so bounds are not lost."],example:"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    size_t count = 3;\n    int *values = malloc(count * sizeof *values);\n    if (!values) return 1;\n    for (size_t i = 0; i < count; i++) values[i] = (int)i * 10;\n    printf(\"%d\\n\", values[2]);\n    free(values);\n    return 0;\n}",output:"20"},
  { id:"reallocate-memory",title:"Reallocate memory",section:"C Memory",summary:"realloc changes an allocation's size and may move it, so use a temporary pointer.",content:["`realloc` may keep the same address or move the allocation. On success, the old pointer is invalidated and the returned pointer must be used; on failure, the original allocation remains valid.","Store the result in a temporary pointer so a failed resize does not lose the original allocation. Handle size calculations and zero-size requests deliberately."],example:"#include <stdlib.h>\nint main(void) {\n    size_t count = 2;\n    int *items = malloc(count * sizeof *items);\n    if (!items) return 1;\n    int *grown = realloc(items, 4 * sizeof *items);\n    if (!grown) { free(items); return 1; }\n    items = grown;\n    free(items);\n    return 0;\n}"},
  { id:"deallocate-memory",title:"Deallocate memory",section:"C Memory",summary:"free releases memory obtained from an allocation function.",content:["Call `free` once for each successful allocation, using the original allocation pointer. `free(NULL)` is safe, but freeing a pointer that was not allocated or already freed is undefined behavior.","After releasing an allocation, do not access it again. Setting one pointer to `NULL` can prevent accidental reuse through that variable, though other aliases may still dangle."],example:"#include <stdlib.h>\nint main(void) {\n    char *buffer = malloc(32);\n    if (!buffer) return 1;\n    buffer[0] = '\\0';\n    free(buffer);\n    buffer = NULL;\n    return 0;\n}"},
  { id:"structs-memory",title:"Structures and memory",section:"C Memory",summary:"A struct can own allocated data when its lifetime and cleanup rules are clearly defined.",content:["A struct may contain pointers to separately allocated objects. Copying the struct copies pointer values, not the allocated data, which can cause shared ownership or double-free bugs.","Document who owns each allocation and provide a cleanup function. Deep copies must allocate and copy the pointed-to data deliberately."],example:"#include <stdlib.h>\nstruct Buffer { char *data; size_t length; };\nvoid destroy_buffer(struct Buffer *buffer) {\n    if (buffer) { free(buffer->data); buffer->data = NULL; buffer->length = 0; }\n}\nint main(void) { struct Buffer buffer = {0}; destroy_buffer(&buffer); return 0; }"},
  { id:"memory-example",title:"Memory management example",section:"C Memory",summary:"A safe allocation example checks failure, uses the allocated region, and frees it.",content:["Dynamic allocation is a sequence: calculate a valid size, allocate, check success, use only the requested elements, and release the allocation.","In real code, design cleanup paths so every successful allocation is released even when a later operation fails. Tools such as sanitizers can help find memory errors during development."],example:"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    size_t count = 3;\n    int *scores = malloc(count * sizeof *scores);\n    if (!scores) return 1;\n    scores[0] = 8; scores[1] = 9; scores[2] = 10;\n    int total = scores[0] + scores[1] + scores[2];\n    printf(\"Average: %.1f\\n\", total / (double)count);\n    free(scores);\n    return 0;\n}",output:"Average: 9.0"},
  { id:"memory-mistakes",title:"Common memory mistakes",section:"C Memory",summary:"Out-of-bounds access, uninitialized reads, dangling pointers, and leaks are common C memory bugs.",content:["A buffer overflow writes beyond an object's bounds; a use-after-free accesses an object after its lifetime. Both can crash programs or corrupt data and must be prevented.","Initialize variables, validate lengths, check allocation results, and keep ownership rules clear. Compiler warnings and memory sanitizers can catch many problems early."],example:"#include <stdlib.h>\nint main(void) {\n    int *number = malloc(sizeof *number);\n    if (!number) return 1;\n    *number = 5;\n    free(number);\n    number = NULL; /* Do not dereference after free. */\n    return 0;\n}"},
  { id:"errors",title:"Errors and diagnostics",section:"C Errors",summary:"Compiler diagnostics, return codes, and library error indicators help locate failures.",content:["A syntax error prevents compilation; a warning points to suspicious code; a runtime error happens while a program runs. Compile with warnings enabled and fix warnings rather than ignoring them.","Standard library functions often report errors through return values. Read documentation for each function and handle failures at the point where they occur."],example:"#include <stdio.h>\nint main(void) {\n    if (puts(\"Hello\") == EOF) return 1;\n    return 0;\n}",output:"Hello"},
  { id:"error-handling",title:"Error handling",section:"C Errors",summary:"C functions commonly report errors with return values, sentinel values, or output parameters.",content:["Unlike languages with exceptions, C APIs commonly return a status code or a special value such as `NULL` or `EOF`. Check that result before continuing.","Use `perror` or `errno` when the function's documentation says they apply. Do not assume `errno` was updated unless the function reported an error."],example:"#include <stdio.h>\nint main(void) {\n    FILE *file = fopen(\"missing.txt\", \"r\");\n    if (!file) { perror(\"fopen\"); return 1; }\n    fclose(file);\n    return 0;\n}"},
  { id:"null",title:"NULL pointers",section:"C Errors",summary:"NULL represents a pointer that points to no object and must not be dereferenced.",content:["Use `NULL` to represent an absent object pointer. Check pointers that may be null before accessing members or dereferencing them.","`NULL` is a pointer constant, not a universal zero value. In modern C, use `nullptr` only in C23 code with a supporting implementation; older standards use `NULL`."],example:"#include <stdio.h>\nint main(void) {\n    const char *name = NULL;\n    if (name) puts(name);\n    else puts(\"No name provided\");\n    return 0;\n}",output:"No name provided"},
  { id:"input-validation",title:"Input validation",section:"C Errors",summary:"Validate input format and range before using it in calculations or array indexes.",content:["Treat user and file input as untrusted data. Check that conversion succeeds, that no unexpected characters remain, and that the value fits the range your program accepts.","Validate before indexing arrays, allocating memory, or performing arithmetic that could overflow. Give the user a useful message when input is rejected."],example:"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    char line[64];\n    if (!fgets(line, sizeof line, stdin)) return 1;\n    char *end;\n    long value = strtol(line, &end, 10);\n    if (end == line || value < 1 || value > 100) { puts(\"Enter 1 to 100\"); return 1; }\n    printf(\"Accepted: %ld\\n\", value);\n    return 0;\n}"},
  { id:"problem-solving",title:"Problem solving in C",section:"C Problem Solving",summary:"Translate a problem into inputs, outputs, steps, and clear conditions before coding.",content:["Restate the task in your own words and identify the input, expected output, constraints, and examples. Break the solution into small steps before choosing C types and data structures.","Implement one step at a time, compile often, and compare the program's result with a hand-worked example. Clear variable names help map the program back to the plan."],example:"/* Find the largest value in a non-empty array. */\n#include <stdio.h>\nint main(void) {\n    int values[] = {4, 9, 2};\n    int largest = values[0];\n    for (size_t i = 1; i < 3; i++) if (values[i] > largest) largest = values[i];\n    printf(\"Largest: %d\\n\", largest);\n    return 0;\n}",output:"Largest: 9"},
  { id:"build-logic",title:"Build the logic",section:"C Problem Solving",summary:"Use sequence, selection, and repetition to express the steps of a solution.",content:["Sequence runs statements in order, selection chooses a path, and repetition performs steps more than once. Most beginner problems can be described using these three building blocks.","Write pseudocode or a small example before coding. Check that every branch produces a sensible result and every loop has a clear stopping condition."],example:"#include <stdio.h>\nint main(void) {\n    int value = 7;\n    int absolute = value < 0 ? -value : value;\n    printf(\"Absolute value: %d\\n\", absolute);\n    return 0;\n}",output:"Absolute value: 7"},
  { id:"edge-cases",title:"Edge cases and errors",section:"C Problem Solving",summary:"Edge cases are unusual valid inputs; error cases are inputs or events the program cannot handle normally.",content:["Think about smallest and largest allowed values, empty input, repeated values, and boundary conditions. These cases often reveal off-by-one errors or missing checks.","Separate valid edge cases from invalid input and define the expected behavior for both. Check arithmetic ranges and allocation failures as part of the design."],example:"#include <stdio.h>\nint main(void) {\n    int values[] = {5};\n    size_t count = 1;\n    int largest = values[0];\n    for (size_t i = 1; i < count; i++) if (values[i] > largest) largest = values[i];\n    printf(\"Single item: %d\\n\", largest);\n    return 0;\n}",output:"Single item: 5"},
  { id:"test-cases",title:"Test cases",section:"C Problem Solving",summary:"Test representative, boundary, and invalid inputs against expected results.",content:["A test case pairs an input with an expected result. Include a typical case, smallest and largest supported values, boundary values, and malformed input where relevant.","Run tests after changes and compare actual results with expected results. Small helper functions are easier to test than one large `main` function."],example:"#include <assert.h>\nint maximum(int a, int b) { return a > b ? a : b; }\nint main(void) {\n    assert(maximum(3, 7) == 7);\n    assert(maximum(-2, -5) == -2);\n    assert(maximum(4, 4) == 4);\n    return 0;\n}"},
  { id:"projects",title:"C projects",section:"C Projects",summary:"Small projects help combine C types, functions, input, and problem solving.",content:["Start with a clear goal and a small feature list. A number guessing game, unit converter, or text-based score tracker can practice conditions, loops, functions, and input validation.","Split the work into functions, test normal and boundary inputs, and build one feature at a time. Keep data sizes bounded and check every input and allocation."],example:"/* A tiny temperature converter core. */\n#include <stdio.h>\ndouble celsius_to_fahrenheit(double c) { return c * 9.0 / 5.0 + 32.0; }\nint main(void) {\n    printf(\"20 C = %.1f F\\n\", celsius_to_fahrenheit(20));\n    return 0;\n}",output:"20 C = 68.0 F"},
  { id:"date-time",title:"Date and time",section:"C More",summary:"The time library provides calendar-time types and functions such as time and strftime.",content:["Include `<time.h>` for clock and calendar-time facilities. `time` obtains calendar time where supported; `localtime` converts it to local broken-down time, and `strftime` formats it.","Time representations and supported ranges vary by implementation. Check function results and do not assume a fixed width for `time_t`."],example:"#include <stdio.h>\n#include <time.h>\nint main(void) {\n    time_t now = time(NULL);\n    if (now == (time_t)-1) return 1;\n    struct tm *local = localtime(&now);\n    if (!local) return 1;\n    char text[32];\n    if (strftime(text, sizeof text, \"%Y-%m-%d\", local)) puts(text);\n    return 0;\n}"},
  { id:"random-numbers",title:"Random numbers",section:"C More",summary:"rand produces pseudo-random integers; seed it once and scale results carefully.",content:["The `<stdlib.h>` functions `rand` and `srand` provide a basic pseudo-random sequence. Seed once, often with a changing value, rather than reseeding before every draw.","Modulo reduction can introduce bias unless the range divides the generator's output range. `rand` is not suitable for security-sensitive values; use a platform security API for that."],example:"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    srand(1234); /* fixed seed makes this example repeatable */\n    int sample = rand();\n    printf(\"Sample: %d\\n\", sample);\n    return 0;\n}"},
  { id:"macros",title:"Macros",section:"C More",summary:"The preprocessor expands macros before compilation, so macros do not behave exactly like functions.",content:["`#define` can define constants or function-like macros, and `#include` brings in header declarations. Macro substitution happens before normal C type checking.","Wrap expression parameters and results in parentheses, and avoid evaluating an argument more than once. Prefer typed `const` objects, enums, or functions when those meet the need."],example:"#include <stdio.h>\n#define SQUARE(value) ((value) * (value))\nint main(void) {\n    printf(\"%d\\n\", SQUARE(5));\n    return 0;\n}",output:"25"},
  { id:"organize-code",title:"Organize code",section:"C More",summary:"Split larger programs into source files and headers with clear, guarded declarations.",content:["A header (`.h`) usually contains declarations and shared type definitions; a source file (`.c`) contains function definitions. Include the header in the source file that implements it so declarations stay consistent.","Use include guards or `#pragma once` where supported to prevent duplicate inclusion. Compile and link all required source files, and keep private helpers `static` when they are used only in one file."],example:"/* math_utils.h */\n#ifndef MATH_UTILS_H\n#define MATH_UTILS_H\nint add(int left, int right);\n#endif\n/* math_utils.c defines add; main.c includes the header. */"},
  { id:"storage-classes",title:"Storage classes",section:"C More",summary:"Storage duration and linkage describe how long objects live and which declarations refer to them.",content:["Automatic local objects usually live until their block ends. Static storage duration objects live for the whole program; `static` at file scope also gives an identifier internal linkage.","`extern` can declare an object or function defined elsewhere. Storage and linkage rules are detailed, so prefer simple file-local state and clear declarations when starting out."],example:"#include <stdio.h>\nvoid count_call(void) {\n    static int calls = 0;\n    printf(\"%d\\n\", ++calls);\n}\nint main(void) { count_call(); count_call(); return 0; }",output:"1\n2"},
  { id:"bitwise-operators",title:"Bitwise operators",section:"C More",summary:"Bitwise operators work on integer bits and are useful for flags and low-level representations.",content:["`&`, `|`, `^`, `~`, `<<`, and `>>` operate on integer representations. They differ from logical `&&` and `||`, which work with truth values and short-circuit.","Use unsigned integer types for bit masks and shifts. Avoid shifting by a negative amount or by an amount at least the width of the promoted type."],example:"#include <stdio.h>\nint main(void) {\n    unsigned flags = 0;\n    flags |= 1u << 2;\n    printf(\"enabled: %d\\n\", (flags & (1u << 2)) != 0);\n    return 0;\n}",output:"enabled: 1"},
  { id:"fixed-width-integers",title:"Fixed-width integers",section:"C More",summary:"stdint.h provides integer types with specified widths when the implementation supports them.",content:["Include `<stdint.h>` for types such as `uint32_t` and `int64_t`. Exact-width types are optional when the implementation has no matching integer representation.","Use `size_t` for object sizes and indexes, and `<inttypes.h>` format macros when printing fixed-width integer types portably."],example:"#include <inttypes.h>\n#include <stdint.h>\n#include <stdio.h>\nint main(void) {\n    uint32_t count = 3000;\n    printf(\"count=%\" PRIu32 \"\\n\", count);\n    return 0;\n}",output:"count=3000"},
  { id:"command-line-args",title:"Command-line arguments",section:"C More",summary:"main can receive an argument count and an array of null-terminated argument strings.",content:["Use `int main(int argc, char *argv[])` to receive command-line arguments. `argc` counts entries and `argv[0]` is conventionally the program name; check `argc` before accessing an argument.","Arguments are strings, so parse and validate them before use. For numbers, `strtol` provides better error checking than a simple conversion."],example:"#include <stdio.h>\nint main(int argc, char *argv[]) {\n    if (argc < 2) { puts(\"Usage: program NAME\"); return 1; }\n    printf(\"Hello, %s!\\n\", argv[1]);\n    return 0;\n}",output:"Running as program Ada: Hello, Ada!"},
  { id:"dsa-intro",title:"Data structures and algorithms",section:"C DSA",summary:"Data structures organize values and algorithms describe steps for solving problems.",content:["A data structure determines how values are stored and accessed. An algorithm describes operations such as searching, sorting, or traversing those values.","Choose a structure based on the operations your program needs. In C, memory ownership and bounds are part of the design, not details to postpone."],example:"/* Linear search checks values one by one. */\n#include <stddef.h>\nint find_value(const int values[], size_t count, int target) {\n    for (size_t i = 0; i < count; i++) if (values[i] == target) return (int)i;\n    return -1;\n}"},
  { id:"searching",title:"Searching",section:"C DSA",summary:"Linear search checks each item, while binary search repeatedly halves a sorted range.",content:["Linear search works on any array and takes time proportional to the number of items. Binary search is faster for large sorted arrays, but the data must remain sorted.","For binary search, maintain a range that may contain the target and carefully avoid off-by-one errors. Use index types and range checks that match the array size."],example:"#include <stddef.h>\nint binary_search(const int a[], size_t n, int target) {\n    size_t lo = 0, hi = n;\n    while (lo < hi) {\n        size_t mid = lo + (hi - lo) / 2;\n        if (a[mid] == target) return (int)mid;\n        if (a[mid] < target) lo = mid + 1; else hi = mid;\n    }\n    return -1;\n}"},
  { id:"sorting",title:"Sorting",section:"C DSA",summary:"Sorting puts items in an order so they can be displayed or searched more easily.",content:["A sorting algorithm rearranges items according to a comparison rule. Simple algorithms are useful for learning; standard library `qsort` can sort arrays using a comparator.","A comparator for `qsort` must return a negative, zero, or positive result without overflowing. Sorting stability and performance depend on the algorithm."],example:"#include <stdio.h>\n#include <stdlib.h>\nint compare_ints(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\nint main(void) { int a[] = {4, 1, 3}; qsort(a, 3, sizeof a[0], compare_ints); printf(\"%d %d %d\\n\", a[0], a[1], a[2]); return 0; }",output:"1 3 4"},
  { id:"stacks",title:"Stacks",section:"C DSA",summary:"A stack follows last-in, first-out order: the most recently added item is removed first.",content:["Stacks support push and pop operations. They can be implemented with an array plus a size, or with linked nodes; every implementation needs capacity or allocation checks.","Stacks are useful for undo histories, parsing, and tracking nested work. Define what pop does when the stack is empty."],example:"#include <stdio.h>\nint main(void) {\n    int stack[3], size = 0;\n    stack[size++] = 10; stack[size++] = 20;\n    int top = stack[--size];\n    printf(\"Popped: %d\\n\", top);\n    return 0;\n}",output:"Popped: 20"},
  { id:"queues",title:"Queues",section:"C DSA",summary:"A queue follows first-in, first-out order: the earliest added item is removed first.",content:["Queues add items at the back and remove them from the front. A circular buffer reuses array space efficiently by wrapping indexes around.","Track both the number of queued items and the buffer capacity so full and empty states are unambiguous. Check capacity before adding."],example:"#include <stdio.h>\nint main(void) {\n    int queue[4] = {12, 24, 0, 0};\n    size_t head = 0, count = 2;\n    printf(\"Next: %d\\n\", queue[head]);\n    head = (head + 1) % 4; count--;\n    (void)head; (void)count;\n    return 0;\n}",output:"Next: 12"},
  { id:"linked-lists",title:"Linked lists",section:"C DSA",summary:"A linked list connects nodes through pointers and can grow one node at a time.",content:["Each list node stores a value and a pointer to the next node. Inserting at the head can be constant time, but finding an item requires walking the list.","Allocate each node carefully and free every node when finished. Update links in a safe order so nodes are not lost."],example:"#include <stdio.h>\nstruct Node { int value; struct Node *next; };\nint main(void) {\n    struct Node second = {20, NULL};\n    struct Node first = {10, &second};\n    for (struct Node *node = &first; node; node = node->next) printf(\"%d \", node->value);\n    return 0;\n}",output:"10 20"},
  { id:"trees",title:"Trees",section:"C DSA",summary:"A tree is a branching structure of nodes connected by parent and child links.",content:["A binary tree node can have up to two children. Binary search trees keep smaller values on one side and larger values on the other, which can make lookup efficient when balanced.","An unbalanced tree may behave like a list. Recursive traversals are common, but very deep trees may require an iterative traversal or careful depth limits."],example:"#include <stdio.h>\nstruct Node { int value; struct Node *left, *right; };\nvoid print_in_order(const struct Node *node) {\n    if (!node) return;\n    print_in_order(node->left);\n    printf(\"%d \", node->value);\n    print_in_order(node->right);\n}"},
  { id:"hash-tables",title:"Hash tables",section:"C DSA",summary:"A hash table uses a hash function to map keys to slots for fast average lookup.",content:["A hash function turns a key into an integer used to choose a table slot. Different keys can collide, so a table needs a collision strategy such as chaining or open addressing.","Performance depends on the hash function, table size, and load factor. Always handle collisions correctly and compare keys after a hash match."],example:"/* Basic hash idea for a short string. */\n#include <stddef.h>\nsize_t hash_text(const char *text) {\n    size_t hash = 5381;\n    while (*text) hash = hash * 33u + (unsigned char)*text++;\n    return hash;\n}"},
  { id:"big-o",title:"Big O notation",section:"C DSA",summary:"Big O describes how an algorithm's resource use grows as input size increases.",content:["O(1) is constant growth, O(n) grows with the number of items, and O(n²) often comes from nested loops over the same data. Big O focuses on growth rather than exact timing.","It helps compare approaches, but actual speed also depends on constants, input patterns, and hardware. Consider memory use as well as runtime."],example:"/* One pass over n values is O(n). */\n#include <stddef.h>\nlong sum_values(const int values[], size_t count) {\n    long sum = 0;\n    for (size_t i = 0; i < count; i++) sum += values[i];\n    return sum;\n}"},
  { id:"certificate",title:"C certificate preparation",section:"C Cert",summary:"A study plan and regular practice help prepare for a C programming assessment.",content:["Review core syntax, types, operators, branches, loops, arrays, strings, functions, pointers, structures, files, and memory safety. Be able to explain what a short code sample does.","Practice writing small programs from a blank file, tracing output, finding bugs, and explaining tradeoffs. Use a checklist of topics and revisit areas where practice questions reveal gaps."],example:"/* Practice: state the output, then compile and check. */\n#include <stdio.h>\nint main(void) { int n = 3; printf(\"%d\\n\", n * n); return 0; }",output:"9"},
  { id:"examples",title:"C examples",section:"C Examples",summary:"Short complete programs make it easier to see how C concepts work together.",content:["A useful example has a clear purpose, includes the headers it needs, checks important errors, and can be compiled on its own. Build examples around one idea at a time.","Trace the code before running it, then change an input or condition and predict what will happen. This develops understanding beyond copying code."],example:"#include <stdio.h>\nint main(void) {\n    int numbers[] = {2, 4, 6};\n    int total = 0;\n    for (size_t i = 0; i < 3; i++) total += numbers[i];\n    printf(\"Total: %d\\n\", total);\n    return 0;\n}",output:"Total: 12"},
  { id:"real-life-examples",title:"Real-life C examples",section:"C Examples",summary:"C is often used where direct hardware access, predictable performance, or small runtimes matter.",content:["C appears in operating systems, embedded devices, compilers, and libraries. These settings value predictable resource use and the ability to work close to hardware.","Real systems require careful testing, review, and platform knowledge. Small learning examples show concepts, but production code needs stronger error handling and security review."],example:"/* A small sensor reading check. */\n#include <stdio.h>\nint main(void) {\n    double temperature = 22.5;\n    if (temperature < 0.0 || temperature > 50.0) puts(\"Check sensor\");\n    else puts(\"Reading looks plausible\");\n    return 0;\n}",output:"Reading looks plausible"},
  { id:"exercises",title:"C exercises",section:"C Examples",summary:"Exercises build fluency by asking you to apply one or more C ideas independently.",content:["Begin with a small task such as converting units, summing an array, or counting vowels. Write down expected inputs and outputs before coding.","After your first solution works, try boundary cases and improve the organization. Compile with warnings and explain why your program is correct."],example:"/* Exercise: count positive values. */\n#include <stddef.h>\nsize_t count_positive(const int a[], size_t n) {\n    size_t count = 0;\n    for (size_t i = 0; i < n; i++) if (a[i] > 0) count++;\n    return count;\n}"},
  { id:"quiz",title:"C quiz",section:"C Examples",summary:"A quiz checks whether you can recall C rules and apply them to small examples.",content:["Use a quiz to find topics to review, not as the only way to learn. For each answer, explain the rule that supports it and compile code when output is uncertain.","Review wrong answers by returning to the related lesson and trying a new example. Pay special attention to pointers, array bounds, and integer conversions."],example:"/* Predict the output. */\n#include <stdio.h>\nint main(void) { int x = 5; printf(\"%d\\n\", x % 2); return 0; }",output:"1"},
  { id:"code-challenges",title:"C code challenges",section:"C Examples",summary:"Code challenges help practice planning, implementation, and checking edge cases.",content:["Read the full prompt and identify input limits before choosing an algorithm. Build a small example by hand and decide what result should be produced.","Write a correct simple solution first, then improve it if constraints require. Test empty, minimum, maximum, and repeated-value cases when relevant."],example:"/* Challenge helper: return the number of digits in a non-negative integer. */\nunsigned digits(unsigned value) {\n    unsigned count = 1;\n    while (value >= 10) { value /= 10; count++; }\n    return count;\n}"},
  { id:"practice-problems",title:"C practice problems",section:"C Examples",summary:"Repeated practice with varied problems strengthens problem-solving and C fundamentals.",content:["Choose problems that cover different skills: loops, arrays, strings, functions, structs, and file handling. Explain your plan before writing code.","Track solutions that were tricky and revisit them later without looking. Compare clarity and safety, not just whether one test passes."],example:"/* Practice: compute the average of a non-empty array. */\n#include <stddef.h>\ndouble average(const int a[], size_t n) {\n    long total = 0;\n    for (size_t i = 0; i < n; i++) total += a[i];\n    return n ? (double)total / n : 0.0;\n}"},
  { id:"compiler",title:"C compiler",section:"C Examples",summary:"A C compiler checks source code and translates it into object code or an executable.",content:["A compiler typically preprocesses includes and macros, compiles source, and links needed code into a program. Common choices include GCC and Clang, with platform-specific alternatives available.","Use standard selection and warning flags appropriate to your toolchain. Compiler output can differ by platform, so use portable C unless you intentionally rely on an extension."],example:"/* Example command: cc -std=c17 -Wall -Wextra -Wpedantic main.c -o main */\n#include <stdio.h>\nint main(void) { puts(\"Compiled successfully\"); return 0; }",output:"Compiled successfully"},
  { id:"syllabus",title:"C syllabus",section:"C Examples",summary:"A C syllabus organizes learning from basic expressions through memory and data structures.",content:["A sensible path starts with setup, syntax, variables, types, expressions, decisions, and loops. Next learn arrays, strings, functions, pointers, structures, files, and memory management.","Finish with debugging, input validation, code organization, and data structures. Revisit earlier topics through small projects and practice problems."],example:"/* A learning checkpoint: function + array + loop. */\n#include <stddef.h>\nint sum(const int a[], size_t n) { int total = 0; for (size_t i = 0; i < n; i++) total += a[i]; return total; }"},
  { id:"study-plan",title:"C study plan",section:"C Examples",summary:"A steady study plan mixes short lessons, coding practice, review, and reflection.",content:["Study one connected group of topics at a time. Read a lesson, type and modify its example, then solve a small task without copying the answer.","At the end of each session, write down what you learned and one question to revisit. Schedule review so foundational ideas remain fresh as topics become more advanced."],example:"/* A simple weekly rhythm: learn, code, review. */\n#include <stdio.h>\nint main(void) { puts(\"Read one topic, build one example, explain one idea.\"); return 0; }",output:"Read one topic, build one example, explain one idea."},
  { id:"interview-qa",title:"C interview questions",section:"C Examples",summary:"Interview preparation combines clear explanations with careful reasoning about C behavior.",content:["Practice explaining pointers, arrays, strings, storage duration, struct layout, and dynamic allocation in your own words. Trace code carefully instead of guessing.","When answering, state assumptions and discuss safety: bounds, lifetimes, null checks, and error handling. If unsure, reason from the C rules rather than bluffing."],example:"/* Interview prompt: why pass the length with an array pointer? */\n#include <stddef.h>\nint contains(const int *items, size_t count, int target) {\n    for (size_t i = 0; i < count; i++) if (items[i] == target) return 1;\n    return 0;\n}"},
  { id:"reference",title:"C reference",section:"C Reference",summary:"A C reference is a quick lookup for language syntax and standard library declarations.",content:["Use a reference to check exact function signatures, macros, headers, and type requirements. C standards define portable behavior while compilers may document extra extensions.","When a detail matters, check the standard or a reliable reference for the language version you target. Do not assume behavior from one compiler applies everywhere."],example:"#include <stdio.h>\nint main(void) {\n    printf(\"C standard version macro: %ld\\n\", (long)__STDC_VERSION__);\n    return 0;\n}"},
  { id:"keywords",title:"C keywords",section:"C Reference",summary:"Keywords are reserved words with defined meaning in the C language.",content:["Words such as `int`, `return`, `if`, `struct`, and `while` are keywords and cannot be used as ordinary identifiers. The set of keywords depends on the C standard version.","Choose descriptive names that do not conflict with keywords or reserved identifier patterns. Compiler-specific extensions may introduce additional reserved names."],example:"#include <stdio.h>\nint main(void) {\n    int total = 2;\n    return total == 2 ? 0 : 1;\n}"},
  { id:"preprocessor",title:"C preprocessor",section:"C Reference",summary:"The preprocessor handles directives such as include, define, and conditional compilation before compilation.",content:["Preprocessor directives begin with `#` and are processed before the compiler parses ordinary C declarations. Common directives include `#include`, `#define`, `#if`, and `#ifdef`.","Use include guards in headers and keep macros simple. Conditional compilation can support platform differences, but too many branches make code hard to maintain."],example:"#include <stdio.h>\n#define MESSAGE \"Hello from a macro\"\nint main(void) { puts(MESSAGE); return 0; }",output:"Hello from a macro"},
  { id:"assert-h",title:"assert.h",section:"C Reference",summary:"assert checks a programmer assumption during development and can stop the program when it is false.",content:["Include `<assert.h>` to use `assert(expression)`. If the expression is false and assertions are enabled, the program prints a diagnostic and calls `abort`.","Assertions are for internal conditions, not user input validation, because defining `NDEBUG` disables them. Do not put required side effects inside an assert expression."],example:"#include <assert.h>\nint main(void) {\n    int total = 2 + 3;\n    assert(total == 5);\n    return 0;\n}"},
  { id:"ctype-h",title:"ctype.h",section:"C Reference",summary:"ctype.h provides character classification and case-conversion functions.",content:["Functions such as `isalpha`, `isdigit`, `isspace`, `tolower`, and `toupper` classify or convert characters according to the current locale.","Pass `EOF` or a value representable as `unsigned char`; passing a negative plain `char` other than EOF has undefined behavior. Cast input chars to `unsigned char` when needed."],example:"#include <ctype.h>\n#include <stdio.h>\nint main(void) {\n    unsigned char letter = 'a';\n    printf(\"%c\\n\", toupper(letter));\n    return 0;\n}",output:"A"},
  { id:"errno-h",title:"errno.h",section:"C Reference",summary:"errno provides an error indicator used by some library functions when they report failure.",content:["Include `<errno.h>` for `errno` and symbolic error values. A function's return value signals whether an error occurred; consult `errno` only when its documentation says it is meaningful.","`errno` is not automatically cleared after a successful call. Set it to zero before functions such as `strtol` when you need to distinguish range errors."],example:"#include <errno.h>\n#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    errno = 0; char *end;\n    long value = strtol(\"42\", &end, 10);\n    if (errno == 0 && *end == '\\0') printf(\"%ld\\n\", value);\n    return 0;\n}",output:"42"},
  { id:"limits-h",title:"limits.h",section:"C Reference",summary:"limits.h defines implementation-specific minimum and maximum values for integer types.",content:["Include `<limits.h>` for macros such as `INT_MAX`, `INT_MIN`, `CHAR_BIT`, and `UINT_MAX`. These values describe the limits of the implementation's types.","Check limits before arithmetic that could overflow. Signed integer overflow is undefined behavior, so do not rely on wraparound."],example:"#include <limits.h>\n#include <stdio.h>\nint main(void) {\n    printf(\"int range: %d to %d\\n\", INT_MIN, INT_MAX);\n    return 0;\n}"},
  { id:"math-h",title:"math.h",section:"C Reference",summary:"math.h declares common floating-point math functions and constants provided by the implementation.",content:["The header declares operations such as `sqrt`, `sin`, `cos`, `floor`, and `ceil`. Function results use floating-point types and may have rounding error.","Check for domain and range errors as appropriate. The toolchain may need an additional math library link option."],example:"#include <math.h>\n#include <stdio.h>\nint main(void) { printf(\"ceil(2.2) = %.0f\\n\", ceil(2.2)); return 0; }",output:"ceil(2.2) = 3"},
  { id:"stdbool-h",title:"stdbool.h",section:"C Reference",summary:"stdbool.h provides bool, true, and false names for boolean values in C99 through C17.",content:["In C99 through C17, include `<stdbool.h>` to use `bool`, `true`, and `false`. In C23, these names are language keywords and the header is retained for compatibility.","Boolean expressions are useful for flags and conditions. Keep boolean names positive and specific, such as `is_ready`."],example:"#include <stdbool.h>\n#include <stdio.h>\nint main(void) {\n    bool ready = false;\n    ready = true;\n    printf(\"%s\\n\", ready ? \"ready\" : \"waiting\");\n    return 0;\n}",output:"ready"},
  { id:"stddef-h",title:"stddef.h",section:"C Reference",summary:"stddef.h defines common types and macros such as size_t, NULL, and offsetof.",content:["`size_t` is the unsigned integer type used for object sizes. `<stddef.h>` also declares `ptrdiff_t`, `wchar_t`, `NULL`, and the `offsetof` macro.","Use `size_t` for array lengths and byte sizes. Avoid assuming that it has the same width as `int`."],example:"#include <stddef.h>\n#include <stdio.h>\nstruct Item { char tag; int value; };\nint main(void) { printf(\"value offset: %zu\\n\", offsetof(struct Item, value)); return 0; }"},
  { id:"stdint-h",title:"stdint.h",section:"C Reference",summary:"stdint.h defines optional exact-width and useful minimum-width integer types.",content:["The header provides types such as `int_least32_t`, `uint_fast16_t`, and optional exact-width types such as `uint32_t`. It also provides limits and constant-construction macros.","Use an exact-width type only when the exact representation width is required and available. For portable sizes, prefer `size_t`; for formatted output use `<inttypes.h>`."],example:"#include <inttypes.h>\n#include <stdint.h>\n#include <stdio.h>\nint main(void) { uint16_t port = 8080; printf(\"%\" PRIu16 \"\\n\", port); return 0; }",output:"8080"},
  { id:"stdio-h",title:"stdio.h",section:"C Reference",summary:"stdio.h declares standard input, output, and file-stream functions.",content:["The header declares `printf`, `fgets`, `FILE`, `fopen`, and many other stream operations. Standard streams include `stdin`, `stdout`, and `stderr`.","Check functions' return values and close streams you open. Match format specifiers to the exact argument types."],example:"#include <stdio.h>\nint main(void) {\n    fprintf(stdout, \"output\\n\");\n    fprintf(stderr, \"diagnostic\\n\");\n    return 0;\n}",output:"Writes output and diagnostic lines to their respective streams"},
  { id:"stdlib-h",title:"stdlib.h",section:"C Reference",summary:"stdlib.h declares utilities for conversion, memory allocation, process control, and sorting.",content:["The header includes `malloc`, `calloc`, `realloc`, `free`, `strtol`, `qsort`, `abs`, and `exit`. Each function has specific input and error rules.","Read function documentation, check return values, and choose safe conversions. For string-to-number conversion, `strtol` allows better validation than `atoi`."],example:"#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    char *end; long number = strtol(\"27\", &end, 10);\n    if (*end == '\\0') printf(\"%ld\\n\", number);\n    return 0;\n}",output:"27"},
  { id:"string-h",title:"string.h",section:"C Reference",summary:"string.h declares functions for working with null-terminated strings and raw memory.",content:["Common functions include `strlen`, `strcmp`, `strchr`, `memcpy`, and `memmove`. These functions do not automatically know the size of your destination buffer.","Ensure strings are terminated and buffers have enough space. Use `memmove` rather than `memcpy` when source and destination regions overlap."],example:"#include <stdio.h>\n#include <string.h>\nint main(void) {\n    const char *word = \"hello\";\n    printf(\"length=%zu, compare=%d\\n\", strlen(word), strcmp(word, \"hello\"));\n    return 0;\n}",output:"length=5, compare=0"},
  { id:"time-h",title:"time.h",section:"C Reference",summary:"time.h declares calendar-time types and conversion and formatting functions.",content:["The header defines `time_t`, `struct tm`, and functions such as `time`, `difftime`, and `strftime`. Calendar conversions may use shared internal storage, so consult the function requirements.","Check results for failure and account for locale and time zone when formatting. Use monotonic clocks from platform APIs for precise elapsed-time measurement."],example:"#include <stdio.h>\n#include <time.h>\nint main(void) {\n    time_t now = time(NULL);\n    if (now == (time_t)-1) return 1;\n    printf(\"seconds value available\\n\");\n    return 0;\n}",output:"seconds value available"},
];

export const cLessons: LearningLesson[] = topics.map(makeLesson);
